def keep_solved_puzzles(apps, schema_editor):
    """
    A puzzle with any completed branch counts as solved. Attempts that wait for the user to pick a reply start over,
    because the opponent replies by itself from now on.
    """
    UserChessPuzzle = apps.get_model("puzzles", "UserChessPuzzle")
    for progress in UserChessPuzzle.objects.all():
        if progress.completed_branches:
            progress.solved_at = progress.updated_at
        if len(progress.line) % 2 and not progress.solved_at:
            progress.line = []
            progress.hint_level = 0
        progress.save(update_fields=["solved_at", "line", "hint_level"])


